import React, { useMemo, useState } from 'react';
import {
  Alert,
  Box,
  LinearProgress,
  Step,
  StepLabel,
  Stepper,
  Typography,
} from '@mui/material';
import OrchestrationRunPanel, { type OrchestrationStage } from '../compliance/OrchestrationRunPanel';
import {
  buildInitialStagedOrchestrationState,
  runStagedReportOrchestration,
  type ReportOrchestrationProfile,
  type StagedOrchestrationStageState,
} from '../../utils/runStagedReportOrchestration';

export type ReportGenerationStepperProps = {
  period?: string;
  exportApplicable?: boolean;
  profile?: ReportOrchestrationProfile;
  running?: boolean;
  stages?: StagedOrchestrationStageState[];
};

export const useStagedReportGeneration = ({
  period = 'annual',
  exportApplicable = false,
  profile = 'standard',
}: {
  period?: string;
  exportApplicable?: boolean;
  profile?: ReportOrchestrationProfile;
} = {}) => {
  const [running, setRunning] = useState(false);
  const [stages, setStages] = useState<StagedOrchestrationStageState[]>(() =>
    buildInitialStagedOrchestrationState(profile, false)
  );
  const [error, setError] = useState<string | null>(null);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [partialFailures, setPartialFailures] = useState<
    Array<{ type?: string; id?: string; message?: string }>
  >([]);

  const run = async (options?: { profile?: ReportOrchestrationProfile; runWorkflows?: boolean }) => {
    const resolvedProfile = options?.profile ?? profile;
    setRunning(true);
    setError(null);
    setFeedback(null);
    setPartialFailures([]);
    setStages(buildInitialStagedOrchestrationState(resolvedProfile, options?.runWorkflows));

    try {
      const result = await runStagedReportOrchestration({
        period,
        cbamPeriod: 'quarter',
        profile: resolvedProfile,
        runWorkflows: options?.runWorkflows,
        persistResults: true,
        includeBrsrOrchestration: true,
        includeIsoOrchestration: true,
        includePcfOrchestration: exportApplicable,
        includeCbamOrchestration: exportApplicable,
        includeBuyerOrchestration: true,
        includeInventoryReview: true,
        onStageStart: (stage) => {
          setStages((current) =>
            current.map((entry) =>
              entry.stage === stage
                ? { ...entry, status: 'running' }
                : entry
            )
          );
        },
        onStageComplete: (stage, payload) => {
          const stageFailed = (payload.stages as Array<{ status?: string }> | undefined)?.some(
            (entry) => entry.status === 'failed'
          );
          setStages((current) =>
            current.map((entry) =>
              entry.stage === stage
                ? {
                    ...entry,
                    status: stageFailed ? 'failed' : 'completed',
                    error: stageFailed
                      ? (payload.stages as Array<{ error?: string }> | undefined)?.find((e) => e.error)?.error
                      : null,
                  }
                : entry
            )
          );
        },
      });

      setStages(result.stages);
      setPartialFailures(result.partialFailures || []);
      setFeedback(
        result.bundle?.summary?.message
          || `Generated ${result.bundle?.summary?.successCount ?? 0} reports${
            result.bundle?.summary?.failedCount
              ? ` (${result.bundle.summary.failedCount} failed)`
              : ''
          }.`
      );
      return result;
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Report generation failed.');
      throw e;
    } finally {
      setRunning(false);
    }
  };

  return {
    running,
    stages,
    error,
    feedback,
    partialFailures,
    setError,
    setFeedback,
    runStandard: () => run({ profile: 'standard', runWorkflows: false }),
    runFull: () => run({ profile: 'full', runWorkflows: true }),
  };
};

const toOrchestrationStages = (stages: StagedOrchestrationStageState[]): OrchestrationStage[] =>
  stages.map((entry) => ({
    stage: entry.stage,
    status:
      entry.status === 'running'
        ? 'running'
        : entry.status === 'failed'
          ? 'failed'
          : entry.status === 'completed'
            ? 'completed'
            : 'pending',
    error: entry.error,
  }));

const ReportGenerationStepper: React.FC<ReportGenerationStepperProps> = ({
  running = false,
  stages = [],
}) => {
  const activeStep = useMemo(() => {
    const runningIndex = stages.findIndex((entry) => entry.status === 'running');
    if (runningIndex >= 0) {
      return runningIndex;
    }
    const lastCompleted = [...stages].reverse().findIndex((entry) => entry.status === 'completed');
    if (lastCompleted >= 0) {
      return stages.length - 1 - lastCompleted + 1;
    }
    return 0;
  }, [stages]);

  if (!running && stages.every((entry) => entry.status === 'pending')) {
    return null;
  }

  return (
    <Box sx={{ mt: 1 }}>
      {running ? (
        <Alert severity="info" sx={{ mb: 2 }}>
          <Typography variant="subtitle2" gutterBottom>
            Generating reports in stages…
          </Typography>
          <LinearProgress sx={{ mt: 1, mb: 1 }} />
          <Typography variant="caption" color="text.secondary">
            Each stage runs as a separate lightweight request so large reports do not time out.
          </Typography>
        </Alert>
      ) : null}

      <Stepper activeStep={Math.min(activeStep, Math.max(stages.length - 1, 0))} alternativeLabel sx={{ mb: 2 }}>
        {stages.map((entry) => (
          <Step key={entry.stage} completed={entry.status === 'completed'}>
            <StepLabel
              error={entry.status === 'failed'}
            >
              {entry.label}
            </StepLabel>
          </Step>
        ))}
      </Stepper>

      <OrchestrationRunPanel
        title="Report generation progress"
        stages={toOrchestrationStages(stages)}
        running={running}
        compact
      />
    </Box>
  );
};

export default ReportGenerationStepper;
